"""Public marketing and legal pages for SocialPilot AI."""
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()

SHELL = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101828"><title>{title} | SocialPilot AI</title><style>
:root{color-scheme:light;--ink:#101828;--muted:#667085;--blue:#4263eb;--line:#e4e7ec;--bg:#f7f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 Inter,system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--blue)}header{padding:18px 5vw;display:flex;justify-content:space-between;align-items:center;background:#101828;color:white}header a{color:white;text-decoration:none}.brand{font-weight:850;font-size:20px;letter-spacing:-.6px}.brand span{color:#9db2ff}nav{display:flex;gap:18px;flex-wrap:wrap}main{max-width:1080px;margin:auto;padding:54px 22px}h1{font-size:clamp(36px,6vw,62px);line-height:1.04;letter-spacing:-2px;margin:16px 0}h2{letter-spacing:-.7px;line-height:1.2}p{color:var(--muted)}.eyebrow{color:var(--blue);font-weight:800;text-transform:uppercase;letter-spacing:1.5px;font-size:12px}.hero{display:grid;grid-template-columns:1.1fr .9fr;gap:32px;align-items:center}.panel,.tile{background:white;border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 12px 40px #1018280a}.button{display:inline-block;padding:12px 18px;border-radius:11px;background:var(--blue);color:white;text-decoration:none;font-weight:750;margin:8px 8px 0 0}.button.secondary{background:white;color:var(--ink);border:1px solid var(--line)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:30px 0}.tag{display:inline-block;background:#eef2ff;color:#3048c8;border-radius:99px;padding:5px 10px;font-size:12px;font-weight:800}.steps{padding-left:20px}.foot{border-top:1px solid var(--line);padding:24px 5vw;display:flex;gap:18px;flex-wrap:wrap}.foot a{color:var(--muted)}@media(max-width:760px){.hero,.grid{grid-template-columns:1fr}main{padding:34px 16px}header{align-items:flex-start;gap:12px;flex-direction:column}}
</style></head><body><header><a class="brand" href="/sell">SocialPilot <span>AI</span></a><nav><a href="/sell#features">Features</a><a href="/sell#how">How it works</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav></header>{body}<footer class="foot"><span>© SocialPilot AI</span><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="https://github.com/parmarharmad-art/Social-ai">Project repository</a></footer></body></html>"""

@router.get("/sell", response_class=HTMLResponse, include_in_schema=False)
async def sales_page():
    body = """<main><section class="hero"><div><div class="eyebrow">Social media workspace</div><h1>Plan better content. Keep your workflow in one place.</h1><p>SocialPilot AI is a mobile-friendly workspace for drafting social posts, organizing a content queue, and connecting an Instagram account. Start with editable content drafts and configure AI and publishing integrations when your accounts are approved.</p><a class="button" href="/workspace">Open workspace</a><a class="button secondary" href="/setup">Check setup</a><p><span class="tag">Early access</span> This is an early-access product. Availability of AI generation and publishing depends on provider configuration and Meta permissions.</p></div><div class="panel"><div class="eyebrow">Your workflow</div><h2>From idea to post</h2><ol class="steps"><li>Choose a topic and draft the post</li><li>Review caption, CTA and hashtags</li><li>Design or upload a visual</li><li>Connect Instagram and configure publishing</li><li>Review queue and results</li></ol><p>Always review content before publishing. No engagement or growth outcome is guaranteed.</p></div></section><section id="features"><h2>Built for practical content operations</h2><div class="grid"><article class="tile"><h3>Content drafts</h3><p>Organize hooks, captions, calls to action and hashtags in an editable package.</p></article><article class="tile"><h3>Mobile-first studio</h3><p>Use the built-in design workspace from a phone, with supported formats for social creatives.</p></article><article class="tile"><h3>Instagram workflow</h3><p>Connect eligible accounts and manage publishing after required Meta permissions and credentials are configured.</p></article></div></section><section id="how" class="panel"><h2>Getting started</h2><p>Open the workspace, review setup status, and connect only accounts you own or are authorized to manage. AI provider usage and third-party platform requirements may incur separate costs.</p><a class="button" href="/workspace">Launch workspace</a><a class="button secondary" href="/setup">Configuration checklist</a></section><section class="panel" style="margin-top:18px"><h2>Early-access commercial status</h2><p>Customer account and workspace features are being tested and signup is currently closed. Billing is not active. Do not enter payment details or use this early-access service for client data until the operator confirms launch readiness.</p></section></main>"""
    return HTMLResponse(SHELL.replace("{title}", "Social media workspace").replace("{body}", body))

@router.get("/privacy", response_class=HTMLResponse, include_in_schema=False)
async def privacy_page():
    body = """<main><div class="eyebrow">Legal information</div><h1>Privacy notice</h1><p><strong>Draft notice for early access — must be reviewed and completed by the operator before commercial launch.</strong></p><h2>Information handled</h2><p>Depending on configuration, the service may process content topics, captions, uploaded/generated media, technical logs, configuration status, and Instagram account identifiers. If connected, Instagram access tokens are intended to be encrypted at rest in the configured database.</p><h2>Third-party services</h2><p>The service may send prompts to an AI provider when AI features are configured and may exchange data with Meta/Instagram to support account connection or publishing. Their terms and privacy policies also apply.</p><h2>Retention and security</h2><p>Data may remain in the configured database and service logs until deleted by the operator. No online service can promise absolute security. Do not submit passwords, payment card details, sensitive personal data, or information you are not authorized to process.</p><h2>Your requests</h2><p>Before accepting customers, the operator must publish a monitored privacy contact, define deletion/retention periods, and implement account/data deletion procedures.</p><h2>Notice status</h2><p>This is a starter notice, not legal advice or a finalized compliance statement. It must be reviewed for the operator's jurisdiction and actual data flows before public commercial use.</p></main>"""
    return HTMLResponse(SHELL.replace("{title}", "Privacy notice").replace("{body}", body))

@router.get("/terms", response_class=HTMLResponse, include_in_schema=False)
async def terms_page():
    body = """<main><div class="eyebrow">Legal information</div><h1>Terms of use</h1><p><strong>Draft terms for early access — must be reviewed and completed by the operator before commercial launch.</strong></p><h2>Early-access service</h2><p>The service is provided for evaluation and may be incomplete, unavailable or changed without notice. No service-level guarantee is offered.</p><h2>Account and platform access</h2><p>You must use only accounts you own or are authorized to manage, comply with Meta and AI-provider terms, and keep your credentials confidential. Third-party approval is not guaranteed.</p><h2>Content responsibility</h2><p>You are responsible for reviewing generated text and media, obtaining rights and permissions, checking claims, and approving every post. The service does not guarantee reach, engagement, leads, sales or business results.</p><h2>Fees and cancellation</h2><p>No self-serve paid subscription or checkout is currently offered through this site. Do not send payment details through the dashboard. Any future paid offer must clearly state its price, billing cycle, cancellation and refund terms before purchase.</p><h2>Operator details</h2><p>The operator must add their legal/business name, a monitored contact address, governing law and dispute process before accepting paying customers. This starter text is not legal advice.</p></main>"""
    return HTMLResponse(SHELL.replace("{title}", "Terms of use").replace("{body}", body))
